  "Cancelled": {"ca": "Cancel·lat", "es": "Cancelado"},
  "This bone is connected to its parent: it can only rotate.": {"ca": "Aquest os està connectat al seu pare: només pot girar.", "es": "Este hueso está conectado a su padre: solo puede girar."},
  "{b} follows {c}: select {c} (its box) to move it.": {"ca": "{b} segueix {c}: selecciona {c} (la seva caixa) per moure'l.", "es": "{b} sigue a {c}: selecciona {c} (su caja) para moverlo."},
  "This bone is locked in this lab: it can only rotate.": {"ca": "Aquest os està bloquejat en aquest lab: només pot girar.", "es": "Este hueso está bloqueado en este lab: solo puede girar."},
  "Rotation cleared.": {"ca": "Rotació esborrada.", "es": "Rotación borrada."},
  "Location cleared.": {"ca": "Posició esborrada.", "es": "Posición borrada."},
  "Transforms cleared.": {"ca": "Transformacions esborrades.", "es": "Transformaciones borradas."},
  "To Active Bone needs two selected bones: first the target, then Shift-click the bone that gets the constraint.": {"ca": "To Active Bone necessita dos ossos seleccionats: primer el target, després Shift-clic a l'os que tindrà el constraint.", "es": "To Active Bone necesita dos huesos seleccionados: primero el target, después Shift-clic en el hueso que tendrá el constraint."},
  "This bone has no parent: an IK chain needs at least two bones.": {"ca": "Aquest os no té pare: una cadena IK necessita almenys dos ossos.", "es": "Este hueso no tiene padre: una cadena IK necesita al menos dos huesos."},
  "IK added to {b}.": {"ca": "IK afegit a {b}.", "es": "IK añadido a {b}."},
  "Not part of this lab.": {"ca": "No forma part d'aquest lab.", "es": "No forma parte de este lab."},
