  "click · Shift click": {"ca": "clic · Shift clic", "es": "clic · Shift clic"},
  "IK control": {"ca": "control IK", "es": "control IK"},
  "pole": {"ca": "pole", "es": "pole"},
  "Click a bone to select it.": {"ca": "Fes clic a un os per seleccionar-lo.", "es": "Haz clic en un hueso para seleccionarlo."},
  "XYZ Euler, in degrees. Location and rotation are in the bone's own axes.": {"ca": "XYZ Euler, en graus. La posició i la rotació són en els eixos propis de l'os.", "es": "XYZ Euler, en grados. La posición y la rotación están en los ejes propios del hueso."},
  "Connected to its parent: only rotation. XYZ Euler, in degrees, in the bone's own axes.": {"ca": "Connectat al pare: només rotació. XYZ Euler, en graus, en els eixos propis de l'os.", "es": "Conectado al padre: solo rotación. XYZ Euler, en grados, en los ejes propios del hueso."},
  "Location locked in this lab. XYZ Euler, in degrees, in the bone's own axes.": {"ca": "Posició bloquejada en aquest lab. XYZ Euler, en graus, en els eixos propis de l'os.", "es": "Posición bloqueada en este lab. XYZ Euler, en grados, en los ejes propios del hueso."},
  "Select a bone to see its constraints.": {"ca": "Selecciona un os per veure'n els constraints.", "es": "Selecciona un hueso para ver sus constraints."},
  "Delete constraint": {"ca": "Elimina el constraint", "es": "Elimina el constraint"},
  "Choose a target bone: the tip of the chain will reach for it.": {"ca": "Tria un os target: la punta de la cadena l'anirà a buscar.", "es": "Elige un hueso target: la punta de la cadena irá a buscarlo."},
  "Chain Length 0 = every parent up to the root.": {"ca": "Chain Length 0 = tots els pares fins a l'arrel.", "es": "Chain Length 0 = todos los padres hasta la raíz."},
  "The target is out of reach: the chain stretches out straight.": {"ca": "El target és massa lluny: la cadena s'estira recta.", "es": "El target está demasiado lejos: la cadena se estira recta."},
  "The IK constraint of this armature is on {b}.": {"ca": "El constraint IK d'aquest armature és a {b}.", "es": "El constraint IK de este armature está en {b}."},
  "Readout": {"ca": "Lectures", "es": "Lecturas"},
  "Farthest from the ghost": {"ca": "Distància màxima al fantasma", "es": "Distancia máxima al fantasma"},
  "Fingertips → cup": {"ca": "Punta dels dits → tassa", "es": "Punta de los dedos → taza"},
