  "Fingertips (X Y Z)": {"ca": "Punta dels dits (X Y Z)", "es": "Punta de los dedos (X Y Z)"},
  "Foot → target": {"ca": "Peu → target", "es": "Pie → target"},
  "The knee points": {"ca": "El genoll apunta", "es": "La rodilla apunta"},
